package de.lazytv.pro.playlist;
import de.lazytv.pro.activation.ActivationGuard;import android.app.Activity;import android.app.AlertDialog;import android.content.Intent;import android.os.Bundle;import android.view.View;import android.widget.ListView;import android.widget.TextView;import android.widget.Toast;import de.lazytv.pro.R;import de.lazytv.pro.MainActivity;
public class PlaylistManagerActivity extends Activity {private PlaylistStorage storage; private PlaylistAdapter adapter; private TextView empty;@Override protected void onCreate(Bundle b){super.onCreate(b);if(!ActivationGuard.enforce(this))return;setContentView(R.layout.activity_playlist_manager);storage=new PlaylistStorage(this);adapter=new PlaylistAdapter();ListView list=findViewById(R.id.playlist_list);empty=findViewById(R.id.empty_text);list.setAdapter(adapter);findViewById(R.id.add_playlist).setOnClickListener(v->startActivity(new Intent(this,PlaylistEditorActivity.class)));findViewById(R.id.add_m3u).setOnClickListener(v->openPreset("M3U"));findViewById(R.id.add_xtream).setOnClickListener(v->openPreset("XTREAM"));findViewById(R.id.add_stalker).setOnClickListener(v->openPreset("STALKER"));list.setOnItemClickListener((p,v,pos,id)->showActions(adapter.getItem(pos)));}@Override protected void onResume(){super.onResume();refresh();}private void openPreset(String type){Intent i=new Intent(this,PlaylistEditorActivity.class);i.putExtra("preset_type",type);startActivity(i);}private void refresh(){adapter.submit(storage.getAll(),storage.getActiveId());empty.setVisibility(adapter.getCount()==0?View.VISIBLE:View.GONE);}private void showActions(Playlist item){String[] a={"Use / Open","Edit","Delete"};new AlertDialog.Builder(this).setTitle(item.getName()).setItems(a,(d,w)->{if(w==0)connect(item);else if(w==1)edit(item);else confirmDelete(item);}).show();}private void connect(Playlist item){String err=PlaylistValidator.validateForConnect(this,item);if(err!=null){Toast.makeText(this,err,Toast.LENGTH_LONG).show();return;}storage.setActive(item.getId());refresh();Toast.makeText(this,item.getName()+" active",Toast.LENGTH_SHORT).show();Intent i=new Intent(this,MainActivity.class);i.putExtra("active_playlist_id",item.getId());i.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(i);finish();}private void edit(Playlist item){Intent i=new Intent(this,PlaylistEditorActivity.class);i.putExtra(PlaylistEditorActivity.EXTRA_ID,item.getId());startActivity(i);}private void confirmDelete(Playlist item){new AlertDialog.Builder(this).setTitle("Fshi playlistën?").setMessage(item.getName()).setNegativeButton("Anulo",null).setPositiveButton("Fshi",(d,w)->{storage.delete(item.getId());refresh();}).show();}}
